import{_ as e,o,c as r,ag as a}from"./chunks/framework.qXLDknWC.js";const p=JSON.parse('{"title":"Lorebook Editor","description":"","frontmatter":{},"headers":[],"relativePath":"features/lorebook-editor.md","filePath":"features/lorebook-editor.md"}'),n={name:"features/lorebook-editor.md"};function s(l,t,i,h,c,d){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="lorebook-editor" tabindex="-1">Lorebook Editor <a class="header-anchor" href="#lorebook-editor" aria-label="Permalink to &quot;Lorebook Editor&quot;">​</a></h1><p>The <strong>Lorebook</strong> editor manages SillyTavern-style <strong>World Info</strong> entries: text that can activate on keywords (or always, for constants) and inject into the model context during roleplay.</p><p>The same editor is used in two places:</p><ol><li><strong>Character</strong> workspace → <strong>Lorebook</strong> tab (the lorebook that lives on the card)</li><li><strong>Lorebook vault</strong> → open a standalone book (<a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a>)</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Field help icons (<strong>?</strong>) next to labels summarize SillyTavern World Info behavior. Prefer those for short definitions; this page covers the CharacterVault layout and tools.</p></div><h2 id="two-panel-layout" tabindex="-1">Two-panel layout <a class="header-anchor" href="#two-panel-layout" aria-label="Permalink to &quot;Two-panel layout&quot;">​</a></h2><p>Content stays in front. Extra controls open from the header so the editor can use the space.</p><ul><li><strong>Left sidebar</strong> – Book settings, search, AI context usage, entry list, import/export, new entry</li><li><strong>Right panel</strong> – Entry title, keys, Enabled / Constant, and the content editor</li></ul><p><strong>Options</strong> and (on a character) <strong>Attach</strong> sit in the entry header. Click either to open a panel over the editor; click again, <strong>Done</strong>, or <strong>Escape</strong> to close. Opening one closes the other.</p><p>On a phone, the list and the entry swap: tap a row to edit, <strong>Back</strong> to return to the list. <strong>Attach</strong> is also next to book settings on the list so you can reach it without opening an entry.</p><h2 id="book-settings" tabindex="-1">Book settings <a class="header-anchor" href="#book-settings" aria-label="Permalink to &quot;Book settings&quot;">​</a></h2><p>Expand <strong>Lorebook</strong> at the top of the sidebar:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Setting</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Book name</strong></td><td style="text-align:left;">Display name for the book</td></tr><tr><td style="text-align:left;"><strong>Description</strong></td><td style="text-align:left;">Short description</td></tr><tr><td style="text-align:left;"><strong>Scan depth</strong></td><td style="text-align:left;">How many recent chat messages ST scans for keys (book-level)</td></tr><tr><td style="text-align:left;"><strong>Token budget</strong></td><td style="text-align:left;">Max tokens World Info may consume at once (book-level)</td></tr><tr><td style="text-align:left;"><strong>Recursive scanning</strong></td><td style="text-align:left;">When on, activated entries can unlock others by naming their keys in <strong>Content</strong></td></tr><tr><td style="text-align:left;"><strong>Map</strong></td><td style="text-align:left;">Opens the <a href="#recursion-map">Recursion map</a></td></tr><tr><td style="text-align:left;"><strong>Delete lorebook</strong></td><td style="text-align:left;">Characters only: remove the lorebook from the card (when offered)</td></tr></tbody></table><h2 id="entry-list" tabindex="-1">Entry list <a class="header-anchor" href="#entry-list" aria-label="Permalink to &quot;Entry list&quot;">​</a></h2><p>Each row shows a title (entry title / memo, or a fallback), key count, optional token count for the selected row, context eye, and delete.</p><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>Filter by title, internal notes, content, or primary keys. A result count appears when search is active.</p><h3 id="ai-context-character-vault" tabindex="-1">AI context (Character Vault) <a class="header-anchor" href="#ai-context-character-vault" aria-label="Permalink to &quot;AI context (Character Vault)&quot;">​</a></h3><p>A compact <strong>AI context</strong> block shows how many entries are included and a token usage bar (book token budget when set, otherwise sampler context length).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Eye</strong> on a row</td><td style="text-align:left;">Include or exclude that entry from Orion / AI toolbar context</td></tr><tr><td style="text-align:left;"><strong>All</strong> / <strong>None</strong></td><td style="text-align:left;">Enable or disable context for every entry</td></tr></tbody></table><p>This is <strong>separate</strong> from <strong>Enabled</strong> (SillyTavern activation). See <a href="/CharacterVault/docs/features/ai-context#lorebook-in-context">AI Context → Lorebook</a>.</p><h3 id="import-export" tabindex="-1">Import &amp; export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import &amp; export&quot;">​</a></h3><p>Bottom of the sidebar:</p><ul><li><strong>Import</strong> – Replace the current book’s entries with a JSON lorebook (confirmation if entries already exist)</li><li><strong>Export</strong> – Download ST-compatible JSON</li><li><strong>New Entry</strong> – Append a blank entry and open it</li></ul><h2 id="entry-detail" tabindex="-1">Entry detail <a class="header-anchor" href="#entry-detail" aria-label="Permalink to &quot;Entry detail&quot;">​</a></h2><p>The header title is the ST entry title (memo). It is not sent as content. Next to it: <strong>Attach</strong> (characters only), <strong>Options</strong>, and <strong>Delete</strong>. <strong>Options</strong> shows a small accent dot when this entry has non-default settings.</p><p>Always on screen:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary keys</strong></td><td style="text-align:left;">Keywords or <code>/regex/</code> that can activate the entry</td></tr><tr><td style="text-align:left;"><strong>Enabled</strong></td><td style="text-align:left;">When off, the entry never activates in SillyTavern</td></tr><tr><td style="text-align:left;"><strong>Constant</strong></td><td style="text-align:left;">Always-on; no keyword required</td></tr><tr><td style="text-align:left;"><strong>Content</strong></td><td style="text-align:left;">Text injected when the entry activates (full CodeMirror + AI toolbar)</td></tr></tbody></table><p>Enabled and Constant are pressable chips (accent when on).</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p>Click <strong>Options</strong> to cover the content editor. <strong>Done</strong> or <strong>Escape</strong> closes it. Fields inside:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Secondary keys</strong></td><td style="text-align:left;">Optional filter keys when <strong>Selective</strong> is on</td></tr><tr><td style="text-align:left;"><strong>Selective</strong> + logic</td><td style="text-align:left;">AND ANY / NOT ALL / NOT ANY / AND ALL (ST selectiveLogic)</td></tr><tr><td style="text-align:left;"><strong>Insertion order</strong></td><td style="text-align:left;">Higher numbers insert later / closer to the end of context</td></tr><tr><td style="text-align:left;"><strong>Position</strong></td><td style="text-align:left;">Where content injects (before/after char, before/after example, or at depth)</td></tr><tr><td style="text-align:left;"><strong>Depth / role</strong></td><td style="text-align:left;">For <strong>at depth</strong>: chat depth and system / user / assistant role</td></tr><tr><td style="text-align:left;"><strong>Case sensitive</strong></td><td style="text-align:left;">Exact letter case for keys</td></tr><tr><td style="text-align:left;"><strong>Match whole words</strong></td><td style="text-align:left;">Whole-word style matching for plain keys</td></tr><tr><td style="text-align:left;"><strong>Probability %</strong> / <strong>Use %</strong></td><td style="text-align:left;">Chance the entry is inserted after it would activate</td></tr><tr><td style="text-align:left;"><strong>Non-recursable</strong></td><td style="text-align:left;">Other entries cannot unlock this one via recursive scanning</td></tr><tr><td style="text-align:left;"><strong>Prevent further recursion</strong></td><td style="text-align:left;">When this activates, it will not unlock further entries</td></tr><tr><td style="text-align:left;"><strong>Delay until recursion</strong></td><td style="text-align:left;">Only activates on recursive passes, not the first chat scan</td></tr><tr><td style="text-align:left;"><strong>Internal notes</strong></td><td style="text-align:left;">Optional notes (stored as the entry name field; not ST memo)</td></tr></tbody></table><p>At-a-glance counts: <strong>Triggers N · Triggered by M</strong> (or “No recursion links”), plus <strong>Map</strong>.</p><h2 id="recursion-map" tabindex="-1">Recursion map <a class="header-anchor" href="#recursion-map" aria-label="Permalink to &quot;Recursion map&quot;">​</a></h2><p>A full-screen map of how your entries unlock each other. If entry A&#39;s <strong>content</strong> mentions one of entry B&#39;s <strong>primary keys</strong>, there&#39;s a path from A to B: when A activates, B can activate right after it (as long as flags allow it).</p><h3 id="open-the-map" tabindex="-1">Open the map <a class="header-anchor" href="#open-the-map" aria-label="Permalink to &quot;Open the map&quot;">​</a></h3><ul><li>Entry → <strong>Options</strong> → <strong>Map</strong> (opens with that entry already inspected)</li><li>Book settings → <strong>Map</strong> (opens the whole book)</li></ul><p>Both open the same view; the only difference is whether an entry is pre-selected.</p><h3 id="the-web-view" tabindex="-1">The web view <a class="header-anchor" href="#the-web-view" aria-label="Permalink to &quot;The web view&quot;">​</a></h3><p>By default you get a picture of the whole book. Each box is an entry, each arrow is a path: the entry an arrow starts from mentions the other entry&#39;s keys in its content. Entries group into clusters so you can see which ones belong to the same chain. Little dots on a box show its flags (see the legend at the bottom).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">How</th></tr></thead><tbody><tr><td style="text-align:left;">Move around</td><td style="text-align:left;">Drag the background</td></tr><tr><td style="text-align:left;">Zoom</td><td style="text-align:left;">Scroll wheel, centered on your cursor</td></tr><tr><td style="text-align:left;">Inspect an entry</td><td style="text-align:left;">Click it; click the same box again to clear</td></tr><tr><td style="text-align:left;">Select for bulk edits</td><td style="text-align:left;">Ctrl (or Cmd) + click; click again to deselect</td></tr><tr><td style="text-align:left;">Reset camera</td><td style="text-align:left;"><strong>Reset view</strong></td></tr><tr><td style="text-align:left;">Show entries with no links</td><td style="text-align:left;"><strong>Show standalone</strong></td></tr></tbody></table><p>Hover an entry to light up just its connections and fade everything else. A legend at the bottom of the map explains the arrows and flag dots.</p><h3 id="the-list-view" tabindex="-1">The list view <a class="header-anchor" href="#the-list-view" aria-label="Permalink to &quot;The list view&quot;">​</a></h3><p>Switch to <strong>List</strong> next to the Web button for a plain table of every entry, with search and All / Linked / Standalone filters. Same actions: click a row to inspect (again to clear), use the checkbox to select. For very large books the map opens in list mode first, since a wall of boxes is slower to read and slower to draw.</p><h3 id="inspecting-an-entry" tabindex="-1">Inspecting an entry <a class="header-anchor" href="#inspecting-an-entry" aria-label="Permalink to &quot;Inspecting an entry&quot;">​</a></h3><p>The right-hand panel shows the clicked entry: its keys, flags, who can unlock it, and what it unlocks. From here you can:</p><ul><li>Edit <strong>primary keys</strong> as chips under <strong>Keys</strong>. Click a chip to rename it, <strong>X</strong> to remove it, or type in the field to add one (Enter or comma). These write to the actual entry and update the map immediately. They are the real trigger keys, not map-only labels.</li><li>On <strong>Unlocked by</strong> / <strong>Unlocks</strong> rows, the matched keywords are chips too. <strong>Unlocked by</strong> edits this entry’s keys (<code>Mentions these keys in its content</code>). <strong>Unlocks</strong> edits the <em>other</em> entry’s keys (<code>These keys match in this content</code>). Removing a matched chip on an Unlocks row drops that hop.</li><li>Toggle <strong>Non-recursable</strong>, <strong>Prevent further</strong>, or <strong>Delay until recursion</strong> for just this entry. These apply right away.</li><li><strong>Select</strong> it to add it to a bulk selection.</li></ul><p>Escape while renaming a chip cancels the rename and leaves the map open. Pan and zoom stay put when arrows appear or vanish; use <strong>Reset view</strong> to recenter.</p><p>Clicking another entry in its &quot;Unlocked by&quot; or &quot;Unlocks&quot; lists inspects that one instead, so you can walk a chain step by step. Click the inspected box again, or the inspector <strong>X</strong>, to close the panel and drop the path highlight.</p><h3 id="bulk-flag-changes" tabindex="-1">Bulk flag changes <a class="header-anchor" href="#bulk-flag-changes" aria-label="Permalink to &quot;Bulk flag changes&quot;">​</a></h3><p>Selecting one or more entries opens a bar at the bottom. Pick On or Off for any of the three recursion flags, or use <strong>Isolate: block both directions</strong> (non-recursable plus prevent further). Nothing is applied yet. The bar shows exactly what is staged and for how many entries. Press <strong>Apply</strong> to commit, or <strong>Discard</strong> to back out. For big selections (more than 25 entries), Apply asks for a second click so a stray tap cannot rewrite half the book.</p><p>Quick-select shortcuts in the bar: <strong>All</strong> entries, <strong>Visible</strong> (what search is showing), <strong>Linked</strong> (entries with at least one path), and <strong>Clear</strong>.</p><h3 id="small-print" tabindex="-1">Small print <a class="header-anchor" href="#small-print" aria-label="Permalink to &quot;Small print&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Authoring aid, not a full ST simulator</p><p>The map reads <strong>primary keys</strong> in content (including simple <code>/regex/</code> support, case sensitivity, and whole-word options). Key chips on the map edit those same primary keys. It does <strong>not</strong> fully simulate selective secondary logic, probability, token budget, multi-step depth, or chat scan. Treat it as a guide for wiring keys and recursion flags.</p></div><p>If <strong>Recursive scanning</strong> is off on the book, the map still shows potential key hits and warns that SillyTavern will not recurse until scanning is enabled (book or global ST setting).</p><p>For a walkthrough with examples, see the <a href="/CharacterVault/docs/features/recursion-map-guide">Recursion Map Guide</a>.</p><h2 id="ai-key-generation" tabindex="-1">AI key generation <a class="header-anchor" href="#ai-key-generation" aria-label="Permalink to &quot;AI key generation&quot;">​</a></h2><p>The <strong>sparkle</strong> control next to primary keys asks the AI for 2–5 comma-separated trigger keywords from <strong>Content</strong>, then merges them with existing keys.</p><ul><li>Requires a configured AI provider (<a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a>)</li><li>Uses the <strong>Custom / instruct</strong> prompt model mapping when set; otherwise the global model</li><li>Click again to abort; requests time out after about 15 seconds</li></ul><h2 id="content-editor" tabindex="-1">Content editor <a class="header-anchor" href="#content-editor" aria-label="Permalink to &quot;Content editor&quot;">​</a></h2><p>Entry <strong>Content</strong> uses the shared CodeMirror stack: AI toolbar, spellcheck, macros, Markdown image highlighting, font size. See <a href="/CharacterVault/docs/features/editor">Editor &amp; AI Toolkit</a>.</p><h2 id="import-export-1" tabindex="-1">Import &amp; export <a class="header-anchor" href="#import-export-1" aria-label="Permalink to &quot;Import &amp; export&quot;">​</a></h2><p>Works for both the lorebook on a character and a library book.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><ol><li>Open the lorebook editor (character tab or vault book).</li><li>Click <strong>Export</strong>.</li><li>Save the JSON (SillyTavern-oriented world info).</li></ol><h3 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h3><ol><li>Click <strong>Import</strong> and choose a JSON file.</li><li>If the book already has entries, confirm replacement.</li><li>Supported shapes include CharacterVault / ST lorebook JSON (<code>character_book</code>, <code>entries</code>, etc.).</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Standalone library import (multiple files, keep books separate) is on the <a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a> tab. Character/vault <strong>editor</strong> import replaces the <strong>current</strong> book’s entries.</p></div><h2 id="linking-a-library-book-characters" tabindex="-1">Linking a library book (characters) <a class="header-anchor" href="#linking-a-library-book-characters" aria-label="Permalink to &quot;Linking a library book (characters)&quot;">​</a></h2><p>On a character, <strong>Attach</strong> in the entry header (or next to book settings on a phone) opens the link panel: <strong>Open in vault</strong>, <strong>Attach</strong> / <strong>Replace</strong>, copy, and <strong>Detach</strong>. The button label is <strong>Attach</strong>, the linked book’s name, or <strong>Missing</strong>.</p><p>A character can link <strong>one</strong> book from the Lorebooks library. After you link, you’ll be asked whether to copy that book onto the character (this replaces the lorebook already on the card).</p><p>Once linked, they stay in sync: <strong>Open in vault</strong> writes the character’s current lorebook to the library book; edits in the library workspace update every linked character. The link itself stays in CharacterVault; exporting a card includes the lorebook on that character.</p><p>See <a href="/CharacterVault/docs/features/lorebook-vault#attach-to-a-character-vault-local">Lorebook Vault → Linking</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/recursion-map-guide">Recursion Map Guide</a></li><li><a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a></li><li><a href="/CharacterVault/docs/features/ai-context">AI Context</a></li><li><a href="/CharacterVault/docs/getting-started/creating-characters">Creating &amp; Editing Characters</a></li><li><a href="/CharacterVault/docs/configuration/ai-setup">Configure AI</a></li></ul>',75)])])}const y=e(n,[["render",s]]);export{p as __pageData,y as default};
